import type { IconShape, IconThemeName } from "./placement";

/**
 * The local ByteDance IconPark set.
 *
 * The set is a sibling file, `icons/iconpark.json`, generated by `scripts/build-iconpark.mjs`. It is
 * not embedded in `main.js` because all 2658 icons are ~1.2 MB and Obsidian would parse that on
 * every plugin load; here it is read once, on first use, and only if the user ever picks an icon.
 *
 * Naming follows the `collection:name` convention the wider icon ecosystem uses, so a name like
 * `icon-park:folder-open` can be recognised and looked up outside this plugin.
 *
 * IconPark's themes are why the set is pleasant to work with: `outline` / `filled` / `two-tone` /
 * `duotone` are four colour *mappings* over one static template, not four drawings. So one
 * stored icon serves all four, and switching theme costs nothing in the bundle.
 */

/** One icon as stored: a template still carrying its `C0..C3` palette sentinels. */
export interface StoredIcon {
  readonly viewBox: string;
  readonly body: string;
}

export interface IconSetMeta {
  readonly source: string;
  readonly author: string;
  readonly repo: string;
  /** `icon-park` — the collection prefix, shown in the picker so the name can be copied. */
  readonly prefix: string;
  readonly package: string;
  readonly license: string;
  readonly themes: readonly string[];
  readonly stroke: number;
  readonly strokeLinecap: string;
  readonly strokeLinejoin: string;
  readonly count: number;
  readonly icons: Readonly<Record<string, StoredIcon>>;
}

export const ICON_SET_PATH = "icons/iconpark.json";

let cached: IconSetMeta | null = null;
let pending: Promise<IconSetMeta> | null = null;

export type IconSetLoader = () => Promise<IconSetMeta>;

let defaultLoader: IconSetLoader | null = null;

export function setIconSetLoader(loader: IconSetLoader | null): void {
  cached = null;
  pending = null;
  defaultLoader = loader;
}

export async function loadIconSet(
  loader?: IconSetLoader,
): Promise<IconSetMeta> {
  if (cached) return cached;
  const load = loader ?? defaultLoader;
  if (!load) throw new Error("Auto Icon: no icon-set loader configured");

  // Concurrent callers must share one read, not each start their own.
  if (!pending) {
    pending = load()
      .then((set) => {
        cached = set;
        return set;
      })
      .finally(() => {
        pending = null;
      });
  }
  return pending;
}

export function loadedIconSet(): IconSetMeta | null {
  return cached;
}

export function iconNames(set: IconSetMeta): string[] {
  return Object.keys(set.icons).sort();
}

export function hasIcon(set: IconSetMeta, name: string): boolean {
  return Object.prototype.hasOwnProperty.call(set.icons, name);
}

/**
 * Apply a theme's four colours to a stored template.
 *
 * The sentinels `C0..C3` were left in the markup by the generator precisely so this is a
 * substitution rather than a re-render, which is why four themes cost nothing.
 */
export function shapeFor(
  set: IconSetMeta,
  name: string,
  theme: IconThemeName | string,
  accent?: string,
): IconShape | null {
  const stored = set.icons[name];
  if (!stored) return null;

  const colours = themeColours(theme, accent);
  const body = stored.body.replace(/C([0-3])/g, (_match, slot: string) => {
    const colour = colours[Number(slot) as 0 | 1 | 2 | 3];
    return colour || "currentColor";
  });

  return {
    viewBox: stored.viewBox,
    body,
    stroke: set.stroke,
    strokeLinecap: set.strokeLinecap,
    strokeLinejoin: set.strokeLinejoin,
  };
}

/** Full identifier, e.g. `icon-park:folder-open`. What a user copies out of the plugin. */
export function collectionName(set: IconSetMeta, name: string): string {
  return `${set.prefix}:${name}`;
}

/**
 * Search, ranked rather than merely filtered.
 *
 * Without ranking, searching "folder open" returns every `folder-*` icon in alphabetical order and
 * the one that was asked for never reaches the first page. Hyphens, spaces and underscores are all
 * accepted because people type all three.
 */
export function searchIcons(
  set: IconSetMeta,
  query: string,
  limit = 300,
): string[] {
  const all = iconNames(set);
  const q = query.trim().toLowerCase();
  if (q.length === 0) return all.slice(0, limit);

  const spaced = q.replace(/[-_\s]+/g, " ");
  const exact: string[] = [];
  const prefix: string[] = [];
  const contains: string[] = [];

  for (const name of all) {
    const flat = name.toLowerCase();
    const readable = flat.replace(/[-_]/g, " ");
    if (flat === q || readable === spaced) exact.push(name);
    else if (flat.startsWith(q) || readable.startsWith(spaced))
      prefix.push(name);
    else if (flat.includes(q) || readable.includes(spaced)) contains.push(name);
  }

  return [...exact, ...prefix, ...contains].slice(0, limit);
}

/* ------------------------------------------------------------------ *
 * Themes
 *
 * Theme names are IconPark's own (`outline` / `filled` / `two-tone` / `duotone`) so they can be
 * looked up against IconPark's documentation, while the labels are Chinese.
 *
 * The colours are the plugin's own, not IconPark's defaults (`#333`, `#FFF`, `#2F88FF`): an icon
 * sitting in a note or a file tree has to inherit the surrounding text colour, so slot 0 is
 * `currentColor` and the fill slots are `none`. A hard-coded `#333` would be invisible on a dark
 * theme — the single most common way a plugin's icons quietly disappear.
 * ------------------------------------------------------------------ */

export interface ThemeColours {
  readonly name: IconThemeName;
  readonly label: string;
  /** Slot 0 primary stroke, 1 secondary fill, 2 inner stroke, 3 inner fill. */
  readonly colors: readonly [string, string, string, string];
  /** Whether an accent colour is worth editing. */
  readonly usesAccent: boolean;
}

export const DEFAULT_ACCENT = "#2f88ff";
export const DEFAULT_ACCENT_LIGHT = "#43ccf8";

export const THEME_LIST: readonly ThemeColours[] = [
  {
    name: "outline",
    label: "线性",
    colors: ["currentColor", "none", "currentColor", "none"],
    usesAccent: false,
  },
  {
    name: "filled",
    label: "填充",
    colors: ["currentColor", "currentColor", "none", "none"],
    usesAccent: false,
  },
  {
    name: "two-tone",
    label: "双色",
    colors: ["currentColor", DEFAULT_ACCENT, "currentColor", DEFAULT_ACCENT],
    usesAccent: true,
  },
  {
    name: "duotone",
    label: "双色深浅",
    colors: [
      "currentColor",
      DEFAULT_ACCENT,
      DEFAULT_ACCENT,
      DEFAULT_ACCENT_LIGHT,
    ],
    usesAccent: true,
  },
];

/** True when a theme paints anything other than the text colour, i.e. an accent is worth editing. */
export function themeUsesAccent(theme: string): boolean {
  return (THEME_LIST.find((t) => t.name === theme) ?? THEME_LIST[0]).usesAccent;
}

export function themeColours(
  theme: IconThemeName | string,
  accent = DEFAULT_ACCENT,
): readonly string[] {
  const found = THEME_LIST.find((t) => t.name === theme) ?? THEME_LIST[0];
  if (!found.usesAccent) return found.colors;
  return found.colors.map((c) =>
    c === DEFAULT_ACCENT
      ? accent
      : c === DEFAULT_ACCENT_LIGHT
        ? mixLight(accent)
        : c,
  );
}

/** A lighter companion for the multi-colour theme, derived from the accent. */
function mixLight(accent: string): string {
  if (!/^#[0-9a-f]{6}$/i.test(accent)) return DEFAULT_ACCENT_LIGHT;
  const n = parseInt(accent.slice(1), 16);
  const r = Math.round(((n >> 16) & 0xff) * 0.35 + 255 * 0.65);
  const g = Math.round(((n >> 8) & 0xff) * 0.35 + 255 * 0.65);
  const b = Math.round((n & 0xff) * 0.35 + 255 * 0.65);
  return `#${[r, g, b].map((v) => v.toString(16).padStart(2, "0")).join("")}`;
}
